* { box-sizing: border-box; }
body { margin: 0; min-height: 100vh; display: grid; place-items: center; font-family: Inter, Segoe UI, Arial, sans-serif; background: #111820; color: #f7f2e8; }
.shedder-shell { width: min(1120px, 94vw); padding: 30px 0; }
.shedder-board { padding: clamp(22px, 4vw, 46px); border-radius: 8px; background: linear-gradient(135deg, #172230, #302b1f); border: 1px solid rgba(255,255,255,.15); box-shadow: 0 24px 70px rgba(0,0,0,.35); }
.eyebrow { margin: 0 0 8px; color: #8bd3dd; text-transform: uppercase; font-size: .78rem; font-weight: 800; letter-spacing: .08em; }
h1 { margin: 0; font-size: clamp(2rem, 5vw, 4.65rem); line-height: .96; letter-spacing: 0; }
.summary { max-width: 740px; color: #ded8cf; line-height: 1.65; font-size: 1.05rem; }
.shedder-stage { display: grid; grid-template-columns: 1.3fr .25fr 1fr 1fr; gap: 18px; align-items: center; min-height: 310px; margin-top: 30px; }
.traffic-lanes { display: grid; gap: 12px; padding: 18px; border-radius: 8px; background: rgba(255,255,255,.07); border: 1px solid rgba(255,255,255,.16); }
.traffic-lanes span { height: 20px; border-radius: 99px; background: linear-gradient(90deg, #8bd3dd, transparent); animation: traffic-flow 1.55s linear infinite; }
.traffic-lanes span:nth-child(2) { width: 82%; animation-delay: -.4s; }
.traffic-lanes span:nth-child(3) { width: 68%; animation-delay: -.8s; }
.traffic-lanes span:nth-child(4) { width: 50%; animation-delay: -1.2s; }
.admission-gate { min-height: 230px; display: grid; gap: 8px; position: relative; }
.admission-gate i { border-radius: 99px; background: linear-gradient(#ffd166, #ff7a7a); animation: gate-glow 1.35s ease-in-out infinite; }
.admission-gate i:nth-child(2) { animation-delay: -.55s; }
.admission-gate strong { position: absolute; bottom: -24px; left: 50%; transform: translateX(-50%); color: #ffd166; text-transform: uppercase; font-size: .78rem; }
.priority-core { min-height: 220px; border-radius: 8px; border: 1px solid rgba(155,231,197,.45); background: rgba(155,231,197,.08); display: grid; place-items: center; position: relative; }
.priority-core b { position: absolute; inset: 24%; border-radius: 50%; border: 2px solid rgba(155,231,197,.5); animation: priority-ring 2s ease-out infinite; }
.priority-core b:nth-child(2) { animation-delay: -.9s; }
.priority-core em { color: #9be7c5; text-transform: uppercase; font-style: normal; font-weight: 900; }
.shed-queue { min-height: 220px; display: grid; gap: 12px; align-content: center; padding: 18px; border-radius: 8px; background: rgba(255,122,122,.08); border: 1px solid rgba(255,122,122,.45); }
.shed-queue small { color: #ff9a9a; text-transform: uppercase; font-weight: 900; }
.shed-queue span { height: 24px; border-radius: 6px; background: #ff7a7a; animation: shed-pulse 1.45s ease-in-out infinite; }
.shed-queue span:nth-child(3) { width: 68%; animation-delay: -.7s; }
.readouts { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 24px; }
.readouts span { padding: 9px 12px; border-radius: 6px; background: rgba(255,255,255,.075); border: 1px solid rgba(255,255,255,.16); font-weight: 800; }
@keyframes traffic-flow { from { transform: translateX(-22px); opacity: .25; } 50% { opacity: 1; } to { transform: translateX(70px); opacity: .25; } }
@keyframes gate-glow { 0%,100% { opacity: .55; } 50% { opacity: 1; box-shadow: 0 0 24px rgba(255,122,122,.55); } }
@keyframes priority-ring { from { transform: scale(.58); opacity: .85; } to { transform: scale(1.25); opacity: 0; } }
@keyframes shed-pulse { 0%,100% { transform: scaleX(.82); opacity: .62; } 50% { transform: scaleX(1); opacity: 1; } }
@media (max-width: 820px) { .shedder-stage { grid-template-columns: 1fr; } .admission-gate { min-height: 72px; grid-template-columns: repeat(2, 1fr); } }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; } }
